it('denies capability-provided optional sandbox before registration', async () => {
  const plugin: KernelPlugin = {
    name: 'synthetic.capability.sandbox',
    kind: 'capability',
    provides: ['sandbox'],
    apply(ctx) {
      ctx.provide('sandbox', {
        evaluate: async () => ({ allowed: false })
      } as never)
    }
  }
  await expect(KernelHost.boot([plugin], [])).rejects.toMatchObject({
    code: 'control_service_from_capability'
  })
})

it('permits absent optional sandbox and a trusted control implementation', async () => {
  const absent = await KernelHost.boot([], [])
  expect(absent.has('sandbox')).toBe(false)
  await absent.dispose()
  const sandbox = { evaluate: async () => ({ allowed: false }) }
  const present = await KernelHost.boot(
    [
      {
        name: 'synthetic.control.sandbox',
        kind: 'control',
        provides: ['sandbox'],
        apply(ctx) {
          ctx.provide('sandbox', sandbox as never)
        }
      }
    ],
    []
  )
  expect(present.get('sandbox')).toBe(sandbox)
  await present.dispose()
})
